/**
 * Worker entry point (wrangler.jsonc "main"). Wraps the OpenNext worker so a
 * few paths can be answered before Next.js runs.
 *
 * /ingest/* is a reverse proxy for PostHog: the browser sends analytics to our
 * own domain, which ad blockers leave alone, and this forwards it to PostHog's
 * EU cloud. It lives here rather than in a Next route or rewrite so Next's
 * trailing-slash redirect never touches PostHog's /e/ and /flags/ endpoints.
 *
 * Excluded from tsconfig: ./.open-next/worker.js only exists after cf:build.
 */
// @ts-expect-error -- generated by `opennextjs-cloudflare build`
import { default as handler } from './.open-next/worker.js';

const POSTHOG_API_HOST = 'eu.i.posthog.com';
const POSTHOG_ASSET_HOST = 'eu-assets.i.posthog.com';
const PROXY_PREFIX = '/ingest';

async function proxyPostHog(request: Request, url: URL): Promise<Response> {
  const path = url.pathname.slice(PROXY_PREFIX.length) || '/';
  const host = path.startsWith('/static/') ? POSTHOG_ASSET_HOST : POSTHOG_API_HOST;

  const headers = new Headers(request.headers);
  headers.delete('cookie');
  // Keeps PostHog's country lookup working: without it every visitor would be
  // located at the Cloudflare data centre making the request.
  const clientIp = request.headers.get('cf-connecting-ip');
  if (clientIp) headers.set('x-forwarded-for', clientIp);

  return fetch(`https://${host}${path}${url.search}`, {
    method: request.method,
    headers,
    body: request.method === 'GET' || request.method === 'HEAD' ? undefined : request.body,
    redirect: 'manual',
  });
}

const worker = {
  async fetch(request: Request, env: unknown, ctx: unknown) {
    const url = new URL(request.url);
    if (url.pathname === PROXY_PREFIX || url.pathname.startsWith(`${PROXY_PREFIX}/`)) {
      return proxyPostHog(request, url);
    }
    return handler.fetch(request, env, ctx);
  },
};

export default worker;

// Durable Object classes OpenNext declares; wrangler.jsonc binds DOQueueHandler.
// @ts-expect-error -- generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from './.open-next/worker.js';
